begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir helpers/phase16de_fixtures.sql
create temp table health_context as select j.id job_id,a.subscription_id from public.entitlement_jobs j join public.channel_access a on a.id=j.access_id where j.tenant_id='16de2000-0000-4000-8000-000000000001';
update public.entitlement_jobs set status='FAILED',last_error='TEST_UNKNOWN_EFFECT',lease_token=gen_random_uuid(),lease_until=now()-interval '1 minute' where id=(select job_id from health_context);
insert into private.entitlement_test_runtime(job_id,tenant_id,claims,reclaims,provider_failures,dispatch_started,uncertain)
select job_id,'16de2000-0000-4000-8000-000000000001',3,1,2,true,true from health_context;
create function pg_temp.health() returns jsonb language sql security definer set search_path=pg_catalog as $$
 select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',subscription_id,array[job_id]) from pg_temp.health_context;
$$;
select is(pg_temp.health()->'items'->0->>'reason','UNKNOWN_EFFECT','manager sees actual tracked uncertainty');
select job_id as health_job,subscription_id as health_sub from health_context \gset
set local role authenticated;
select is(public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',:'health_sub',array[:'health_job']::uuid[])->'items'->0->>'reason','UNKNOWN_EFFECT','actual authenticated manager role can use safe wrapper');
select throws_ok($$select * from private.entitlement_test_runtime$$,'42501',null,'actual authenticated raw table SELECT denied');
reset role;
select is(pg_temp.health()->'items'->0->>'claims','3','persisted lifetime claims, not inferred attempts');
select is(pg_temp.health()->'items'->0->>'reclaims','1','separate pre-dispatch counter');
select is(pg_temp.health()->'items'->0->>'provider_failures','2','separate definite provider counter');
select is(pg_temp.health()->'items'->0->>'effect_state','UNCERTAIN','not falsely marked completed');
select is(pg_temp.health()->'items'->0->>'financial_authority','NONE','read cannot confer financial authority');
select is(pg_temp.health()->'items'->0->>'retry_authority','NONE','read cannot reset or retry job');
select is(pg_temp.health()->'items'->0->>'review_required','true','failed review obligation visible');
select ok(pg_temp.health()::text!~'lease_token|lease_until|telegram_user_id|invite_reference|payer|secret','no raw technical secret/identity projection');
select is((select status from public.entitlement_jobs where id=(select job_id from health_context)),'FAILED','reading cannot mutate review');
select is((select count(*)::int from private.entitlement_test_runtime where uncertain),1,'uncertainty not cleared by reading');
select ok(not has_table_privilege('authenticated','private.entitlement_test_runtime','SELECT'),'no raw authenticated runtime read');
select ok(not has_table_privilege('service_role','private.entitlement_test_runtime','UPDATE'),'no new budget reset privilege');
select ok(not has_function_privilege('anon','public.admin_entitlement_job_health_v1(uuid,uuid,uuid[])','EXECUTE'),'anonymous RPC denied');
select ok(not has_function_privilege('service_role','public.admin_entitlement_job_health_v1(uuid,uuid,uuid[])','EXECUTE'),'no service-role Admin bypass');
select set_config('request.jwt.claim.sub','16de1000-0000-4000-8000-000000000002',true);
select is(pg_temp.health()->'items'->0->>'reason','UNKNOWN_EFFECT','support can diagnose without changing authority');
select is(pg_temp.health()->'items'->0->>'retry_authority','NONE','support cannot authorize retry');
insert into auth.users(id) values('16de1000-0000-4000-8000-000000000004');
insert into public.tenant_members(tenant_id,user_id,role) values('16de2000-0000-4000-8000-000000000001','16de1000-0000-4000-8000-000000000004','analyst');
select set_config('request.jwt.claim.sub','16de1000-0000-4000-8000-000000000004',true);
select is(pg_temp.health()->'items'->0->>'reason','RESTRICTED','analyst sensitive reason redacted in SQL');
select ok(pg_temp.health()->'items'->0->'claims'='null'::jsonb,'analyst budget redacted in SQL');
select is(pg_temp.health()->'items'->0->>'effect_state','RESTRICTED','analyst technical effect evidence redacted');
select is(pg_temp.health()->'items'->0->>'lease_state','RESTRICTED','analyst lease evidence redacted');
select set_config('request.jwt.claim.sub','16de1000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.health()$$,'42501','entitlement permission denied','readonly denied independently of UI');
select set_config('request.jwt.claim.sub','16de1000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000002',null,'{}')$$,'42501','entitlement permission denied','wrong tenant membership denied');
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000099','{}')$$,'22023','entitlement scope unavailable','unknown/foreign subscription same unavailable response');
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',(select subscription_id from health_context),array['00000000-0000-4000-8000-000000000099'::uuid])$$,'22023','entitlement scope unavailable','foreign/unknown job same unavailable response');
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',(select subscription_id from health_context),array_fill(gen_random_uuid(),array[101]))$$,'22023','entitlement scope unavailable','oversized independent limit denied');
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',(select subscription_id from health_context),array[(select job_id from health_context),(select job_id from health_context)])$$,'22023','entitlement scope unavailable','duplicate IDs rejected');
select throws_ok($$select public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',(select subscription_id from health_context),array[null::uuid])$$,'22023','entitlement scope unavailable','null cursor-like selector rejected');
select is(jsonb_array_length(public.admin_entitlement_job_health_v1('16de2000-0000-4000-8000-000000000001',(select subscription_id from health_context),'{}')->'items'),0,'empty selected page is complete, not unbounded lookup');
update private.entitlement_test_runtime set uncertain=false,dispatch_started=false where job_id=(select job_id from health_context);
update public.entitlement_jobs set last_error='TEST_RECLAIM_BUDGET_EXHAUSTED' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'reason','RECLAIM_BUDGET','safe reclaim reason allowlist');
update public.entitlement_jobs set last_error='TEST_CLAIM_BUDGET_EXHAUSTED' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'reason','CLAIM_BUDGET','safe lifetime reason allowlist');
update public.entitlement_jobs set last_error='TEST_PROVIDER_FAILURE_BUDGET' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'reason','PROVIDER_FAILURE_BUDGET','provider failure distinct from crash budget');
update public.entitlement_jobs set last_error='provider-error-secret@example.test' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'reason','UNRECORDED','raw free-form provider error never projected');
select ok(pg_temp.health()::text not like '%secret@example.test%','untrusted error text not serialized');
update public.entitlement_jobs set operation='revoke' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'obligation','REVOKE','failed revoke obligation visible');
update public.entitlement_jobs set operation='reconcile' where id=(select job_id from health_context);
select is(pg_temp.health()->'items'->0->>'obligation','RECONCILE','failed repair obligation visible');
update public.subscriptions set revision=revision+1 where id=(select subscription_id from health_context);
select is(pg_temp.health()->'items'->0->>'revision_current','false','outdated job never presented as current');
select is((select count(*)::int from private.verified_payment_receipts),0,'read-only health creates no genuine receipt');
select * from finish();
rollback;
